 static void ScaleBlock(Transaction tr,ObjectId id,double factor,string caption,HashSet<ObjectId> seen){if(!seen.Add(id))return;var b=(BlockTableRecord)tr.GetObject(id,OpenMode.ForRead);foreach(ObjectId child in b){var e=tr.GetObject(child,OpenMode.ForRead);if(e is BlockReference br){ScaleBlock(tr,br.BlockTableRecord,factor,caption,seen);continue;}string s=e is DBText d?d.TextString:e is MText m?m.Text:null;if(s==null)continue;string v=s;if(s.Contains("ESCALA"))v=caption;else if(double.TryParse(s.Trim().TrimEnd('m'),NumberStyles.Float,CultureInfo.InvariantCulture,out var n))v=(n*factor).ToString("0.##",CultureInfo.InvariantCulture)+(s.EndsWith("m")?"m":"");if(v!=s){e.UpgradeOpen();if(e is DBText dt)dt.TextString=v;else((MText)e).Contents=v;}}}
