 static void Clip(Transaction tr,BlockReference br,double width,double height){var center=br.Position.TransformBy(br.BlockTransform.Inverse());var points=new Point2dCollection(new[]{new Point2d(center.X-width/200,center.Y-height/200),new Point2d(center.X+width/200,center.Y-height/200),new Point2d(center.X+width/200,center.Y+height/200),new Point2d(center.X-width/200,center.Y+height/200)});var spatial=new SpatialFilter{Definition=new SpatialFilterDefinition(points,Vector3d.ZAxis,0,0,0,true)};br.CreateExtensionDictionary();var ext=(DBDictionary)tr.GetObject(br.ExtensionDictionary,OpenMode.ForWrite);DBDictionary dict;if(ext.Contains("ACAD_FILTER"))dict=(DBDictionary)tr.GetObject(ext.GetAt("ACAD_FILTER"),OpenMode.ForWrite);else{dict=new DBDictionary();ext.SetAt("ACAD_FILTER",dict);tr.AddNewlyCreatedDBObject(dict,true);}dict.SetAt("SPATIAL",spatial);tr.AddNewlyCreatedDBObject(spatial,true);}
 static void ScaleBar(Transaction tr,BlockTableRecord ps,double x,double y,double step,string caption,ObjectId layer){for(int i=0;i<5;i++){var p=new Polyline{LayerId=layer,ColorIndex=256};p.AddVertexAt(0,new Point2d(x+i*10,y),0,0,0);p.AddVertexAt(1,new Point2d(x+(i+1)*10,y),0,0,0);p.AddVertexAt(2,new Point2d(x+(i+1)*10,y+1.3),0,0,0);p.AddVertexAt(3,new Point2d(x+i*10,y+1.3),0,0,0);p.Closed=true;Add(tr,ps,p);if(i%2==0){var h=new Hatch{LayerId=layer,ColorIndex=256};Add(tr,ps,h);h.SetHatchPattern(HatchPatternType.PreDefined,"SOLID");h.AppendLoop(HatchLoopTypes.External,new ObjectIdCollection(new[]{p.ObjectId}));h.EvaluateHatch(true);}}for(int i=0;i<=5;i++){Text(tr,ps,(i*step).ToString("0.#",CultureInfo.InvariantCulture)+(i==5?"m":""),new Point2d(x+i*10,y+3.8),1.8,layer);}Text(tr,ps,caption,new Point2d(x+25,y-2),1.8,layer);}
 [CommandMethod("JEFEREVISAR")]
 public void Revise(){var doc=App.DocumentManager.MdiActiveDocument;var db=doc.Database;System.Diagnostics.Process.GetCurrentProcess().PriorityClass=System.Diagnostics.ProcessPriorityClass.BelowNormal;LayoutManager.Current.CurrentLayout="MAYORES EVENTOS";db.Cecolor=Color.FromColorIndex(ColorMethod.ByAci,256);var logs=new List<string>();
 using(var tr=db.TransactionManager.StartTransaction()){var layout=(Layout)tr.GetObject(LayoutManager.Current.GetLayoutId("MAYORES EVENTOS"),OpenMode.ForWrite);var ps=(BlockTableRecord)tr.GetObject(layout.BlockTableRecordId,OpenMode.ForWrite);var original=ps.Cast<ObjectId>().ToArray();var anno=Layer(db,tr,"SOTRAMI_008_DETALLES",Color.FromColorIndex(ColorMethod.ByAci,7));
 foreach(ObjectId id in original){var e=tr.GetObject(id,OpenMode.ForRead) as Entity;if(e==null)continue;if(e.Layer.StartsWith("SOTRAMI_008_")){e.UpgradeOpen();e.ColorIndex=256;}if(e is MText m){if(m.Text=="POZA DE MAYORES EVENTOS - PLANTA"){m.UpgradeOpen();m.Contents="POZA DE MAYORES EVENTOS";}if(m.Text=="FORMATO A:1"||m.Text=="FORMATO A:3"){m.UpgradeOpen();m.Erase();}}
 if(e is BlockReference br){var b=(BlockTableRecord)tr.GetObject(br.BlockTableRecord,OpenMode.ForRead);if(b.Name.StartsWith("DETALLE_NORCOBRE_008_")){br.UpgradeOpen();Clip(tr,br,b.Name.EndsWith("ZANJA")?95.1330294295207:27.7078494213528,b.Name.EndsWith("ZANJA")?77.2706731025658:28.8567670938353);logs.Add("DETALLE RECORTADO "+b.Name+" centro MCS="+br.Position.TransformBy(br.BlockTransform.Inverse()));}if(b.Name=="Section Title"){double ox=br.Position.X<300?165.246426347529:457.191476502415;var delta=br.Position-new Point3d(ox,120.447068730026,0);foreach(ObjectId aid in br.AttributeCollection){var a=(AttributeReference)tr.GetObject(aid,OpenMode.ForWrite);a.TransformBy(Matrix3d.Displacement(delta));a.AdjustAlignment(db);}}if(b.Name=="*U140"||b.Name=="*U173"){br.UpgradeOpen();br.Erase();}}
 }
 ScaleBar(tr,ps,674,73,2,"ESCALA 1:200 / FORMATO A1",anno);ScaleBar(tr,ps,754,73,4,"ESCALA 1:400 / FORMATO A3",anno);foreach(ObjectId id in ps){var e=tr.GetObject(id,OpenMode.ForRead) as Entity;if(e!=null&&e.Layer.StartsWith("SOTRAMI_008_")){e.UpgradeOpen();e.ColorIndex=256;if(e is MLeader ml){ml.LeaderLineColor=Color.FromColorIndex(ColorMethod.ByAci,7);if(ml.ContentType==ContentType.MTextContent){using(var mt=ml.MText){mt.ColorIndex=7;ml.MText=mt;}}}}}layout.PlotPlotStyles=true;PlotSettingsValidator.Current.SetCurrentStyleSheet(layout,"WWL-Full.ctb");tr.Commit();}
 var outdir=Path.Combine(Root,"Jefe008","RevisionFinal");Directory.CreateDirectory(outdir);doc.Editor.Regen();db.SaveAs(Path.Combine(outdir,"1107.001.00.14-200-14-P-008-TERMINADO.dwg"),DwgVersion.Current);Plot(db,Path.Combine(outdir,"1107.001.00.14-200-14-P-008-TERMINADO.pdf"));File.WriteAllLines(Path.Combine(outdir,"revision.txt"),logs);doc.Editor.WriteMessage("\nJEFEREVISAR_DONE\n");}
 public static void Plot(Database db,string path){using(var tr=db.TransactionManager.StartTransaction()){var l=(Layout)tr.GetObject(LayoutManager.Current.GetLayoutId("MAYORES EVENTOS"),OpenMode.ForWrite);var val=PlotSettingsValidator.Current;val.SetPlotConfigurationName(l,"DWG To PDF.pc3","ISO_full_bleed_A1_(841.00_x_594.00_MM)");val.SetPlotPaperUnits(l,PlotPaperUnit.Millimeters);val.SetPlotType(l,Autodesk.AutoCAD.DatabaseServices.PlotType.Window);val.SetPlotWindowArea(l,new Extents2d(0,0,841,594));val.SetUseStandardScale(l,true);val.SetStdScaleType(l,StdScaleType.ScaleToFit);val.SetPlotCentered(l,true);val.SetPlotRotation(l,PlotRotation.Degrees000);l.PlotPlotStyles=false;l.PrintLineweights=true;l.DrawViewportsFirst=true;tr.Commit();}
 using(var tr=db.TransactionManager.StartTransaction()){var l=(Layout)tr.GetObject(LayoutManager.Current.GetLayoutId("MAYORES EVENTOS"),OpenMode.ForRead);using(var p=new PlotSettings(false))using(var info=new PlotInfo{Layout=l.ObjectId})using(var valid=new PlotInfoValidator()){p.CopyFrom(l);info.OverrideSettings=p;valid.MediaMatchingPolicy=MatchingPolicy.MatchEnabled;valid.Validate(info);using(var engine=PlotFactory.CreatePublishEngine()){engine.BeginPlot(null,null);engine.BeginDocument(info,App.DocumentManager.MdiActiveDocument.Name,null,1,true,path);using(var page=new PlotPageInfo()){engine.BeginPage(page,info,true,null);engine.BeginGenerateGraphics(null);engine.EndGenerateGraphics(null);engine.EndPage(null);}engine.EndDocument(null);engine.EndPlot(null);}}}}
 [CommandMethod("JEFEBASE")]
 public void Base(){var doc=App.DocumentManager.MdiActiveDocument;var db=doc.Database;var log=new List<string>();var civil=CivilDocument.GetCivilDocument(db);LayoutManager.Current.CurrentLayout="MAYORES EVENTOS";
 using(var tr=db.TransactionManager.StartTransaction()){
 var bt=(BlockTable)tr.GetObject(db.BlockTableId,OpenMode.ForRead);foreach(ObjectId id in bt){var b=(BlockTableRecord)tr.GetObject(id,OpenMode.ForRead);if(!b.IsFromExternalReference || b.IsUnloaded)continue;var file=Path.GetFileName(b.PathName);var p=Path.Combine(Project,"05_Drawing","Xref",file);if(File.Exists(p)){b.UpgradeOpen();b.PathName=p;log.Add("XREF "+b.Name+" "+p);}}
 var imgId=RasterImageDef.GetImageDictionary(db);if(!imgId.IsNull){var dict=(DBDictionary)tr.GetObject(imgId,OpenMode.ForRead);foreach(DBDictionaryEntry entry in dict){var def=tr.GetObject(entry.Value,OpenMode.ForRead) as RasterImageDef;if(def==null)continue;var file=Path.GetFileName(def.SourceFileName);var p=Path.Combine(Root,"Assets",file);if(!File.Exists(p))p=Path.Combine(Project,"05_Drawing","Xref",file);if(File.Exists(p)){def.UpgradeOpen();def.SourceFileName=p;try{def.Load();}catch{}log.Add("IMAGE "+p);}}}
 foreach(ObjectId id in civil.GetSurfaceIds()){var s=(TinSurface)tr.GetObject(id,OpenMode.ForRead);try{log.Add("TIN "+id.Handle+" "+s.Name+" reference="+s.IsReferenceObject+" valid="+s.IsReferenceValid+" triangles="+s.GetTriangles(false).Count);}catch(System.Exception ex){log.Add("TINERROR "+s.Name+" "+ex.Message);}}
 var ps=(BlockTableRecord)tr.GetObject(((Layout)tr.GetObject(LayoutManager.Current.GetLayoutId("MAYORES EVENTOS"),OpenMode.ForRead)).BlockTableRecordId,OpenMode.ForRead);
 foreach(ObjectId id in ps){var en=tr.GetObject(id,OpenMode.ForRead);if(en is Table tab){log.Add("TABLE "+id.Handle);for(int r=0;r<tab.Rows.Count;r++)for(int c=0;c<tab.Columns.Count;c++)log.Add(r+","+c+" "+tab.Cells[r,c].TextString);}if(en is Polyline pl){log.Add("POLY "+id.Handle+" color="+pl.ColorIndex+" closed="+pl.Closed+" "+string.Join(";",Enumerable.Range(0,pl.NumberOfVertices).Select(i=>pl.GetPoint2dAt(i).ToString())));}}
 tr.Commit();}
 try{db.ResolveXrefs(false,false);}catch(System.Exception ex){log.Add("RESOLVE "+ex.Message);}Directory.CreateDirectory(Path.Combine(Root,"Jefe008"));File.WriteAllLines(Path.Combine(Root,"jefe-base.txt"),log);doc.Editor.Regen();Plot(db,Path.Combine(Root,"Jefe008","base.pdf"));db.SaveAs(Path.Combine(Root,"Jefe008","base.dwg"),DwgVersion.Current);doc.Editor.WriteMessage("\nJEFEBASE_DONE\n");}
